<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\TicketService;

Auth::requirePermission('tickets.manage');$tenantId=em_require_tenant();$service=new TicketService();
if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();$action=(string)($_POST['action']??'');try{
    if($action==='checkin'){$token=trim((string)($_POST['token']??''));$r=$service->checkIn($token);em_flash($r['ok']?'ok':'error',$r['ok']?'Check-in realizado.':($r['result']==='duplicate'?'Ingresso já utilizado.':'Ingresso não está liberado para entrada.'));em_go('tickets',['q'=>$token]);}
    if($action==='release-expired'){$n=$service->releaseExpired();Auth::audit('tickets.release_expired','ticket',null,['count'=>$n]);em_flash('ok',$n.' reservas expiradas foram liberadas.');em_go('tickets');}
    if($action==='transfer'){$r=$service->transfer((int)($_POST['ticket_id']??0),['name'=>$_POST['name']??'','email'=>$_POST['email']??'','phone'=>$_POST['phone']??'']);em_flash('ok','Ingresso transferido. O QR antigo foi invalidado e um novo acesso foi gerado para '.$r['name'].'.');em_go('tickets',['q'=>$r['code']]);}
    if($action==='queue-email'){$n=$service->queuePaidTicketsForDelivery($tenantId,300);em_flash('ok',$n.' ingresso(s) elegíveis foram colocados/verificados na fila de e-mail.');em_go('tickets');}
}catch(Throwable$e){em_flash('error',$e->getMessage());em_go('tickets');}}
$q=trim((string)($_GET['q']??''));$sql='SELECT t.*,e.name event_name,b.name batch_name,c.name customer_name,c.email customer_email,c.phone customer_phone,fc.name previous_customer_name FROM tickets t JOIN events e ON e.id=t.event_id JOIN ticket_batches b ON b.id=t.batch_id LEFT JOIN customers c ON c.id=t.customer_id LEFT JOIN customers fc ON fc.id=t.transferred_from_customer_id WHERE t.tenant_id=?';$args=[$tenantId];if($q!==''){$sql.=' AND (t.code=? OR t.qr_token=? OR c.name LIKE ? OR c.email LIKE ?)';array_push($args,$q,$q,'%'.$q.'%','%'.$q.'%');}$sql.=' ORDER BY t.id DESC LIMIT 200';$s=$pdo->prepare($sql);$s->execute($args);$tickets=$s->fetchAll();$stats=[];foreach(['paid'=>'SELECT COUNT(*) FROM tickets WHERE tenant_id=? AND status="paid"','checked'=>'SELECT COUNT(*) FROM tickets WHERE tenant_id=? AND status="checked_in"','reserved'=>'SELECT COUNT(*) FROM tickets WHERE tenant_id=? AND status="reserved"']as$k=>$sqls){$x=$pdo->prepare($sqls);$x->execute([$tenantId]);$stats[$k]=(int)$x->fetchColumn();}$transferId=(int)($_GET['transfer']??0);$transfer=null;if($transferId){foreach($tickets as$t)if((int)$t['id']===$transferId)$transfer=$t;}
em_header('Ingressos e check-in','tickets');?>
<section class="grid"><div class="card metric"><span class="muted">Aguardando entrada</span><strong><?= $stats['paid'] ?></strong></div><div class="card metric"><span class="muted">Check-ins</span><strong><?= $stats['checked'] ?></strong></div><div class="card metric"><span class="muted">Reservados</span><strong><?= $stats['reserved'] ?></strong></div></section><div class="grid" style="grid-template-columns:minmax(280px,1fr) minmax(0,2fr);margin-top:18px"><section class="card"><h2>Validar ingresso</h2><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="checkin"><label>Código / QR<input name="token" required autofocus autocomplete="off"></label><button class="primary" style="margin-top:10px">Realizar check-in</button></form><hr style="border-color:var(--line);margin:24px 0"><div class="actions"><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="release-expired"><button class="secondary">Liberar expirados</button></form><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="queue-email"><button class="secondary">Enviar/reenfileirar ingressos</button></form></div><?php if($transfer):?><hr style="border-color:var(--line);margin:24px 0"><h2>Transferir ingresso</h2><p><strong><?= Security::e($transfer['event_name']) ?></strong><br><span class="muted"><?= Security::e($transfer['code']) ?> · atual: <?= Security::e($transfer['customer_name']??'—') ?></span></p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="transfer"><input type="hidden" name="ticket_id" value="<?= $transferId ?>"><label class="span-2">Novo titular<input name="name" required></label><label>E-mail<input type="email" name="email"></label><label>Telefone<input name="phone"></label><button class="primary span-2">Transferir e invalidar QR antigo</button></form><?php endif;?></section><section class="card"><div class="section-head"><form method="get" class="actions"><input type="hidden" name="route" value="tickets"><input name="q" value="<?= Security::e($q) ?>" placeholder="Código, token, nome ou e-mail"><button class="secondary">Buscar</button></form><?php if(Auth::can('exports.view')):?><a class="button secondary" href="<?= Security::e(em_url('/?route=export&kind=tickets')) ?>">Exportar CSV</a><?php endif;?></div><div class="table-wrap"><table class="table"><thead><tr><th>Ingresso</th><th>Evento / lote</th><th>Titular</th><th>Status</th><th>Transferência</th><th></th></tr></thead><tbody><?php foreach($tickets as$t):?><tr><td><strong><?= Security::e($t['code']) ?></strong></td><td><?= Security::e($t['event_name']) ?><br><span class="muted"><?= Security::e($t['batch_name']) ?></span></td><td><?= Security::e($t['customer_name']??'—') ?><br><small class="muted"><?= Security::e($t['customer_email']??'') ?></small></td><td><span class="badge"><?= Security::e(em_status_label($t['status'])) ?></span><?php if($t['checked_in_at']):?><br><small class="muted"><?= Security::e($t['checked_in_at']) ?></small><?php endif;?></td><td><?php if($t['transferred_at']):?><span class="muted">de <?= Security::e($t['previous_customer_name']??'outro titular') ?><br><?= Security::e($t['transferred_at']) ?></span><?php else:?>—<?php endif;?></td><td><div class="actions"><?php if($t['qr_token']):?><a class="button secondary" target="_blank" href="<?= Security::e(em_url('/ingresso.php?t='.urlencode($t['qr_token']))) ?>">Abrir</a><?php endif;?><?php if($t['status']==='paid'&&!$t['checked_in_at']):?><a class="button secondary" href="<?= Security::e(em_url('/?route=tickets&transfer='.(int)$t['id'])) ?>">Transferir</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section></div><?php em_footer();
